/* @lc app=leetcode id=2392 lang=kotlin */ class Solution { fun topo(k: Int, es: Array<IntArray>): List<Int>? = es.groupBy({ it[0] }, { it[1] }).let { adj -> IntArray(k + 1).also { d -> es.forEach { d[it[1]]++ } }.let { d -> generateSequence((1..k).filter { d[it] == 0 }) { f -> f.flatMap { u -> adj[u].orEmpty() }.filter { --d[it] == 0 }.takeIf { it.isNotEmpty() } }.flatten().toList().takeIf { it.size == k } } } fun buildMatrix(k: Int, rowConditions: Array<IntArray>, colConditions: Array<IntArray>): Array<IntArray> = topo(k, rowConditions)?.let { r -> topo(k, colConditions)?.let { c -> Array(k) { i -> IntArray(k) { j -> if (r[i] == c[j]) r[i] else 0 } } } } ?: arrayOf<IntArray>() }